    },
    {
      "factor": "Hedged Language",
      "polarity": -1,
      "reason_headline": "Ambiguous Profit and Risk Estimates",
      "reason_detailed": "The agent uses hedged language in estimating profits and risk levels, such as 'Estimated profit: $50,000 to $75,000 in 3 months' and 'Risk level: Medium', which indicates a lack of precision and potentially weak diligence."
    },
    {
      "factor": "Insider Trading Risk",
